#include <bits/stdc++.h>
using namespace std;
long long gcdll(long long a,long long b){ return b==0?a:gcdll(b,a%b); }
int main(){
    long long x;
    while (cin >> x && x != 0) {
        vector<long long> nums;
        nums.push_back(x);
        while (cin >> x && x != 0) nums.push_back(x);
        long long g = 0;
        for (size_t i=1;i<nums.size();i++) g = gcdll(g, llabs(nums[i]-nums[0]));
        cout << g << "\n";
    }
}

